fuzz {
fileprivate extension TokenSyntax {
  /// Assuming this token is a `poundAvailableKeyword` or `poundUnavailableKeyword`
  /// returns the opposite keyword.
  var negatedAvailabilityKeyword:
TokenSyntax {
    switch self. /* c */ tokenKind {
    case .poundAvailable:
      return self.with(
\.tokenKind, .poundUnavailable)
    case .poundUnavailable:
      return self.with(\.tokenKind, .poundAvailable)
    default:
      preconditionFailure(
        "The availability token of an AvailabilityConditionSyntax should always be #available or #unavailable"
      )
    }
  }
}
}

